import heapq
import sys

def bfs(l, u, xi, yi, vis):
    # Priority queue: (step, x, y)
    # Since we want min step, we use min-heap
    heap = []
    heapq.heappush(heap, (0, l, u))
    vis[l][u] = 1
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    while heap:
        step, x, y = heapq.heappop(heap)
        if x == xi and y == yi:
            return step
        for dx, dy in directions:
            nx = x + dx
            ny = y + dy
            if nx < 0 or ny < 0:
                continue
            if nx >= 110 or ny >= 110:
                continue
            if vis[nx][ny]:
                continue
            vis[nx][ny] = 1
            heapq.heappush(heap, (step + 1, nx, ny))
    return -1

def main():
    s = sys.stdin.readline().strip()
    if not s:
        return

    length = len(s)
    x = 0
    y = 0
    xx = 0
    yy = 0

    for i in range(length):
        if s[i] == 'L':
            y -= 1
        elif s[i] == 'R':
            y += 1
        elif s[i] == 'U':
            x -= 1
        elif s[i] == 'D':
            x += 1
        xx = min(xx, x)
        yy = min(yy, y)

    xx = -xx
    yy = -yy

    # Initialize vis to 1 (blocked)
    vis = [[1] * 110 for _ in range(110)]

    x = xx
    y = yy
    for i in range(length):
        if s[i] == 'L':
            y -= 1
        elif s[i] == 'R':
            y += 1
        elif s[i] == 'U':
            x -= 1
        elif s[i] == 'D':
            x += 1
        vis[x][y] = 0

    ans = bfs(xx, yy, x, y, vis)

    if ans == length:
        print("OK")
    else:
        print("BUG")

if __name__ == "__main__":
